import{_ as s,C as n,o as t,c as i,a3 as a,b as l,w as o,a as d,E as h,a2 as c}from"./chunks/framework.D0yITwTA.js";const v=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),p={name:"guide/introduction.md"};function u(g,e,f,m,b,E){const r=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>OWL-SDA</strong> (OWL Synthetic Data AI-Agent) is a Java tool that generates synthetic RDF instance data from OWL ontologies using Large Language Models (LLMs).</p><p>Given an input ontology (in Turtle or RDF/XML format) and a natural-language prompt describing the desired data, OWL-SDA:</p><ol><li>Loads and optionally reasons over the ontology (including fetching external imports).</li><li>Derives SHACL shapes from the OWL class descriptions.</li><li>Dispatches a <strong>supervisor</strong> agent that coordinates a pool of <strong>worker</strong> agents, each responsible for generating instances for a subset of SHACL shapes.</li><li>Validates the generated triples against the SHACL shapes after each round.</li><li>Passes the final output to a <strong>reviewer</strong> agent that either accepts it or requests targeted revisions.</li></ol><h2 id="how-a-run-flows" tabindex="-1">How a run flows <a class="header-anchor" href="#how-a-run-flows" aria-label="Permalink to &quot;How a run flows&quot;">​</a></h2>',5)),(t(),l(c,null,{default:o(()=>[h(r,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22Input%20ontology%3Cbr%2F%3ETurtle%20or%20RDF%2FXML%22%5D%20--%3E%20B%5B%22Resolve%20owl%3Aimports%3Cbr%2F%3EOntologyExtractor%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22Reason%20over%20the%20model%3Cbr%2F%3EOntologyReasoner%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Derive%20SHACL%20shapes%3Cbr%2F%3Easserted%20%2B%20inferred%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Supervisor%20picks%20the%3Cbr%2F%3Enext%20batch%20of%20shapes%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22delegate_tasks%20to%20the%3Cbr%2F%3Eworker%20pool%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22Workers%20write%20triples%3Cbr%2F%3Einto%20the%20shared%20triple%20store%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22Flush%20to%20output%20file%3Cbr%2F%3E%2B%20SHACL%20validation%22%5D%0A%20%20%20%20H%20--%3E%20I%7B%22All%20shapes%20done%3Cbr%2F%3Eand%200%20violations%3F%22%7D%0A%20%20%20%20I%20--%20no%20--%3E%20E%0A%20%20%20%20I%20--%20yes%20--%3E%20J%5B%22Supervisor%20finalises%3Cbr%2F%3Ethe%20output%22%5D%0A%20%20%20%20J%20--%3E%20K%5B%22Reviewer%20inspects%3Cbr%2F%3Ethe%20full%20output%22%5D%0A%20%20%20%20K%20--%3E%20L%7B%22Verdict%22%7D%0A%20%20%20%20L%20--%20%22REVISION_REQUESTED%22%20--%3E%20E%0A%20%20%20%20L%20--%20%22ACCEPTED%20%2F%20REJECTED%22%20--%3E%20M%5B%22Final%20output%20file%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>The generation loop is bounded: consecutive rounds that delegate to nobody, make no progress, or leave the same violations untouched abort the run instead of looping forever. Review iterations are capped by <code>client.reviewer.max-review-attempts</code>, and the last attempt must end in ACCEPTED or REJECTED.</p><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><h3 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Role</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>Supervisor</strong></td><td>Orchestrates the generation loop, assigns shapes to workers, and finalises the output.</td></tr><tr><td><strong>Worker (pool)</strong></td><td>Generates RDF triples for its assigned shapes and writes them to the shared triple store.</td></tr><tr><td><strong>Reviewer</strong></td><td>Reviews the fully assembled output and signals ACCEPTED, REJECTED, or REVISION_REQUESTED.</td></tr></tbody></table><p>Each role has its own model, timeouts, and tool permissions. See the <a href="./configuration">Configuration Reference</a> and <a href="./architecture">Architecture</a>.</p><h3 id="shacl-shapes" tabindex="-1">SHACL Shapes <a class="header-anchor" href="#shacl-shapes" aria-label="Permalink to &quot;SHACL Shapes&quot;">​</a></h3><p>OWL-SDA automatically generates <a href="https://www.w3.org/TR/shacl/" target="_blank" rel="noreferrer">SHACL</a> NodeShapes from <code>owl:Class</code> definitions, including property shapes derived from <code>owl:Restriction</code> axioms. These shapes are used both to guide the workers and to validate the output after each generation round. Shapes are derived twice — from the asserted model and from the <a href="./reasoner">reasoner</a>&#39;s inferred model — and can be cached to disk via <code>shacl.output-dir</code>.</p><h3 id="triple-store" tabindex="-1">Triple Store <a class="header-anchor" href="#triple-store" aria-label="Permalink to &quot;Triple Store&quot;">​</a></h3><p>Workers write triples directly into a shared in-memory triple store. After each delegation round the store is flushed to the configured output file so that the supervisor and reviewer can read it.</p><h3 id="user-context" tabindex="-1">User Context <a class="header-anchor" href="#user-context" aria-label="Permalink to &quot;User Context&quot;">​</a></h3><p>Any number of local files or live URLs can be attached as extra context for the agents — domain notes, worked examples, a PDF, or a specification fetched at runtime. External ontologies referenced through <code>owl:imports</code> are fetched, mirrored, and cached separately; see <a href="./external-ontologies">External Ontologies</a>.</p><h2 id="observing-a-run" tabindex="-1">Observing a run <a class="header-anchor" href="#observing-a-run" aria-label="Permalink to &quot;Observing a run&quot;">​</a></h2><p>Runs are long, so OWL-SDA can show you what it is doing while it works:</p><ul><li><strong>Benchmark snapshots</strong> capture every round — duration, shapes processed, triple count, violations, per-role token usage, and the full message log. See <a href="./benchmarking">Benchmarking</a>.</li><li><strong>A built-in web dashboard</strong>, started with <code>--web-ui</code>, reads those snapshots live and serves them at <code>http://localhost:8080</code>: agent messages and tool calls, the generated output, the triple store, trend charts, and a SHACL violations view. It needs <code>benchmark.enabled: true</code> to have anything to show. See <a href="./web-ui">Web UI</a>.</li></ul><h2 id="supported-llm-backends" tabindex="-1">Supported LLM Backends <a class="header-anchor" href="#supported-llm-backends" aria-label="Permalink to &quot;Supported LLM Backends&quot;">​</a></h2><p>OWL-SDA supports <strong>GitHub Copilot</strong> (via the standalone Copilot CLI), <strong>Ollama</strong> (self-hosted models), and any <strong>OpenAI-compatible endpoint</strong> (bring-your-own-key — OpenAI itself, Azure OpenAI, or self-hosted gateways) as language model backends. Providers can be mixed per role: cheap local workers with a stronger hosted supervisor, for example. Support for additional providers can be added by implementing the <code>Client</code> / <code>Session</code> interfaces.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./installation">Installation</a> — build the jar and set up a backend.</li><li><a href="./quickstart">Quick Start</a> — a first run on a minimal ontology.</li><li><a href="./examples">Examples</a> — three complete, ready-to-run projects.</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>OWL-SDA is distributed under the <strong>GNU General Public License v3.0</strong>. See <a href="./license">License</a> for details and the full license text.</p>',20))])}const w=s(p,[["render",u]]);export{v as __pageData,w as default};
